from pathlib import Path
import os,json
path=Path(os.environ.get('APPDATA',''))/'TgWsProxy'/'config.json'
try:
 config=json.loads(path.read_text(encoding='utf8-sig'))
except Exception as e:
 print(json.dumps({'error':type(e).__name__}));raise SystemExit()
def shape(x):
 if isinstance(x,dict):return {k:shape(v) for k,v in x.items()}
 if isinstance(x,list):return {'type':'list','count':len(x),'sample_schema':shape(x[0]) if x else None}
 return type(x).__name__
print(json.dumps({'config_keys_and_value_types_only':shape(config)},ensure_ascii=True))
